import{_ as p,a0 as t,w as r,s as o,I as a,x as n,a1 as l,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"使用 Linux 命令列工具來了解你的 NVMe 驅動器 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 命令列工具來了解你的 NVMe 驅動器 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 命令列工具來了解你的 NVMe 驅動器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 命令列工具來了解你的 NVMe 驅動器 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210920 Use this Linux command-line tool to learn more about your NVMe drives","title":"使用 Linux 命令列工具來了解你的 NVMe 驅動器","tag":"202109","desc":""},"relativePath":"202109/20210920 Use this Linux command-line tool to learn more about your NVMe drives.md","filePath":"[post].md"}'),m={name:"202109/20210920 Use this Linux command-line tool to learn more about your NVMe drives.md"};function u(c,s,g,h,v,b){const e=t("Link");return r(),o("div",null,[s[27]||(s[27]=a("h1",{id:"使用-linux-命令列工具來了解你的-nvme-驅動器",tabindex:"-1"},[n("使用 Linux 命令列工具來了解你的 NVMe 驅動器 "),a("a",{class:"header-anchor",href:"#使用-linux-命令列工具來了解你的-nvme-驅動器","aria-label":"Permalink to “使用 Linux 命令列工具來了解你的 NVMe 驅動器”"},"​")],-1)),s[28]||(s[28]=a("blockquote",null,[a("p",null,"nvme-cli 命令擁有諸多實用的選項，且它是控制和管理數據一種很好的方式。")],-1)),s[29]||(s[29]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202109/26/102441ux8cy36gy1vggykz.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("NVMe 是指",-1)),s[2]||(s[2]=a("ruby",null,[n("非易失性內存規範"),a("rt",null,"Non-Volatile Memory Express")],-1)),s[3]||(s[3]=n("，它規範了軟件和存儲通過 PCIe 和其他協議（包括 TCP）進行通信的方式。它是由非營利組織領導的 ",-1)),l(e,{href:"https://nvmexpress.org/"},{default:i(()=>[...s[0]||(s[0]=[n("開放規範",-1)])]),_:1}),s[4]||(s[4]=n("，並定義了幾種形式的固態存儲。",-1))]),s[30]||(s[30]=a("p",null,"我的筆記本電腦有一個 NVMe 驅動器，我的台式機也有。而且它們的速度很快。我喜歡我的電腦啓動的速度，以及它們讀寫數據的速度。幾乎沒有延遲。",-1)),s[31]||(s[31]=a("p",null,"沒過多久，我就對驅動這種超高速存儲的技術產生了好奇，所以我做了一些調查。我瞭解到，NVMe 驅動器消耗的電力更少，而提供的數據訪問速度甚至比 SATA 的 SSD 驅動器快得多。這很有趣，但我想知道更多關於我的特定 NVMe 驅動器的信息，我想知道它們與其他驅動器有何區別。我可以安全地擦除驅動器嗎？我怎樣才能檢查它的完整性？",-1)),a("p",null,[s[6]||(s[6]=n("帶着這些問題我在互聯網上搜索，發現了一個開源項目，其中有一系列管理 NVMe 驅動器的工具。它被稱為 ",-1)),l(e,{href:"https://github.com/linux-nvme/nvme-cli"},{default:i(()=>[...s[5]||(s[5]=[n("nvme-cli",-1)])]),_:1}),s[7]||(s[7]=n("。",-1))]),s[32]||(s[32]=d(`<h3 id="安裝-nvme-cli" tabindex="-1">安裝 nvme-cli <a class="header-anchor" href="#安裝-nvme-cli" aria-label="Permalink to “安裝 nvme-cli”">​</a></h3><p>你可以從你的發行版的包管理器中安裝 <code>nvme-cli</code>。例如，在 Fedora、CentOS 或類似系統上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install nvme-cli</span></span></code></pre></div><p>在 Debian、Mint、Elementary 和類似系統上:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install nvme-cli</span></span></code></pre></div><h3 id="探索-nvme-驅動器" tabindex="-1">探索 NVMe 驅動器 <a class="header-anchor" href="#探索-nvme-驅動器" aria-label="Permalink to “探索 NVMe 驅動器”">​</a></h3><p>在安裝 <code>nvme-cli</code> 後，我想探索我的驅動器。<code>nvme-cli</code> 沒有手冊頁，但你可以通過輸入 <code>nvme help</code> 獲得很多幫助：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nvme help</span></span>
<span class="line"><span>nvme-1.14</span></span>
<span class="line"><span>usage: nvme &lt;command&gt; [&lt;device&gt;] [&lt;args&gt;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The &#39;&lt;device&gt;&#39; may be either an NVMe character device (ex: /dev/nvme0) or an</span></span>
<span class="line"><span>nvme block device (ex: /dev/nvme0n1).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The following are all implemented sub-commands:</span></span>
<span class="line"><span> list List all NVMe devices and namespaces on machine</span></span>
<span class="line"><span> list-subsys List nvme subsystems</span></span>
<span class="line"><span> id-ctrl Send NVMe Identify Controller</span></span>
<span class="line"><span> id-ns Send NVMe Identify Namespace, display structure</span></span>
<span class="line"><span> id-ns-granularity Send NVMe Identify Namespace Granularity List, display structure</span></span>
<span class="line"><span> list-ns Send NVMe Identify List, display structure</span></span>
<span class="line"><span> list-ctrl Send NVMe Identify Controller List, display structure</span></span>
<span class="line"><span> nvm-id-ctrl Send NVMe Identify Controller NVM Command Set, display structure</span></span>
<span class="line"><span> primary-ctrl-caps Send NVMe Identify Primary Controller Capabilities</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h3 id="列出所有的-nvme-驅動器" tabindex="-1">列出所有的 NVMe 驅動器 <a class="header-anchor" href="#列出所有的-nvme-驅動器" aria-label="Permalink to “列出所有的 NVMe 驅動器”">​</a></h3><p><code>sudo nvme list</code> 命令列出你機器上所有的 NVMe 設備和命名空間。我用它在 <code>/dev/nvme0n1</code> 找到了一個 NVMe 驅動器。下面是命令輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nvme list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Node SN Model Namespace Usage Format FW Rev</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--------------------- -------------------- ---------------------------------------- --------- -------------------------- ---------------- --------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/dev/nvme0n1    S42GMY9M141281 SAMSUNG MZVLB256HAHQ-000L7 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>214.68 GB / 256.06 GB 512  B + 0 B 0L2QEXD7</span></span></code></pre></div><p>我有一個名為 <code>nvme0n1</code> 的驅動器。它列出了序列號、品牌、容量、固件版本等等。</p><p>通過使用 <code>id-ctrl</code> 子命令，你可以得到更多關於該硬盤和它所支持的特性的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nvme id-ctrl /dev/nvme0n1</span></span>
<span class="line"><span>NVME Identify Controller:</span></span>
<span class="line"><span>vid : 0x144d</span></span>
<span class="line"><span>ssvid : 0x144d</span></span>
<span class="line"><span>sn : S42GMY9M141281</span></span>
<span class="line"><span>mn : SAMSUNG MZVLB256HAHQ-000L7</span></span>
<span class="line"><span>fr : 0L2QEXD7</span></span>
<span class="line"><span>rab : 2</span></span>
<span class="line"><span>ieee : 002538</span></span>
<span class="line"><span>cmic : 0</span></span>
<span class="line"><span>mdts : 9</span></span>
<span class="line"><span>cntlid : 0x4</span></span>
<span class="line"><span>ver : 0x10200</span></span>
<span class="line"><span>rtd3r : 0x186a0</span></span>
<span class="line"><span>rtd3e : 0x7a1200</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h3 id="驅動器健康" tabindex="-1">驅動器健康 <a class="header-anchor" href="#驅動器健康" aria-label="Permalink to “驅動器健康”">​</a></h3><p>你可以通過 <code>smart-log</code> 子命令來了解硬盤的整體健康狀況：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nvme smart-log /dev/nvme0n1</span></span>
<span class="line"><span>Smart Log for NVME device:nvme0n1 namespace-id:ffffffff</span></span>
<span class="line"><span>critical_warning : 0</span></span>
<span class="line"><span>temperature : 21 C</span></span>
<span class="line"><span>available_spare : 100%</span></span>
<span class="line"><span>available_spare_threshold : 10%</span></span>
<span class="line"><span>percentage_used : 2%</span></span>
<span class="line"><span>endurance group critical warning summary: 0</span></span>
<span class="line"><span>data_units_read : 5,749,452</span></span>
<span class="line"><span>data_units_written : 10,602,948</span></span>
<span class="line"><span>host_read_commands : 77,809,121</span></span>
<span class="line"><span>host_write_commands : 153,405,213</span></span>
<span class="line"><span>controller_busy_time : 756</span></span>
<span class="line"><span>power_cycles : 1,719</span></span>
<span class="line"><span>power_on_hours : 1,311</span></span>
<span class="line"><span>unsafe_shutdowns : 129</span></span>
<span class="line"><span>media_errors : 0</span></span>
<span class="line"><span>num_err_log_entries : 1,243</span></span>
<span class="line"><span>Warning Temperature Time : 0</span></span>
<span class="line"><span>Critical Composite Temperature Time : 0</span></span>
<span class="line"><span>Temperature Sensor 1 : 21 C</span></span>
<span class="line"><span>Temperature Sensor 2 : 22 C</span></span>
<span class="line"><span>Thermal Management T1 Trans Count : 0</span></span>
<span class="line"><span>Thermal Management T2 Trans Count : 0</span></span>
<span class="line"><span>Thermal Management T1 Total Time : 0</span></span>
<span class="line"><span>Thermal Management T2 Total Time : 0</span></span></code></pre></div><p>這為你提供了硬盤的當前温度、到目前為止的使用時間、不安全的關機次數等等。</p><h3 id="格式化一個-nvme-驅動器" tabindex="-1">格式化一個 NVMe 驅動器 <a class="header-anchor" href="#格式化一個-nvme-驅動器" aria-label="Permalink to “格式化一個 NVMe 驅動器”">​</a></h3><p>你可以用 <code>nvme-cli</code> 格式化一個 NVMe 驅動器，但要注意。這將刪除驅動器上的所有數據！如果你的硬盤上有重要的數據，你必須在這樣做之前將其備份，否則你<strong>將會</strong>丟失數據。子命令是 <code>format</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nvme format /dev/nvme0nX</span></span></code></pre></div><p>（為了安全起見，我用 <code>X</code> 替換了驅動器的實際位置，以防止複製粘貼的錯誤。將 <code>X</code> 改為 <code>1</code> 或 <code>nvme list</code> 結果中列出的實際位置。）</p><h3 id="安全地擦除-nvme-驅動器" tabindex="-1">安全地擦除 NVMe 驅動器 <a class="header-anchor" href="#安全地擦除-nvme-驅動器" aria-label="Permalink to “安全地擦除 NVMe 驅動器”">​</a></h3><p>當你準備出售或處理你的 NVMe 電腦時，你可能想安全地擦除驅動器。這裏的警告與格式化過程中的警告相同。首先要備份重要的數據，因為這個命令會刪除這些數據！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nvme sanitize /dev/nvme0nX</span></span></code></pre></div><h3 id="嘗試-nvme-cli" tabindex="-1">嘗試 nvme-cli <a class="header-anchor" href="#嘗試-nvme-cli" aria-label="Permalink to “嘗試 nvme-cli”">​</a></h3>`,26)),a("p",null,[s[9]||(s[9]=a("code",null,"nvme-cli",-1)),s[10]||(s[10]=n(" 命令是在 ",-1)),l(e,{href:"https://github.com/linux-nvme/nvme-cli/blob/master/LICENSE"},{default:i(()=>[...s[8]||(s[8]=[n("GPLv2",-1)])]),_:1}),s[11]||(s[11]=n(" 許可下發布的。它是一個強大的命令，有很多有用的選項，用來有效地控制和管理數據。",-1))]),s[33]||(s[33]=a("hr",null,null,-1)),a("p",null,[s[13]||(s[13]=n("via: ",-1)),l(e,{href:"https://opensource.com/article/21/9/nvme-cli"},{default:i(()=>[...s[12]||(s[12]=[n("https://opensource.com/article/21/9/nvme-cli",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=n("作者：",-1)),l(e,{href:"https://opensource.com/users/don-watkins"},{default:i(()=>[...s[14]||(s[14]=[n("Don Watkins",-1)])]),_:1}),s[19]||(s[19]=n(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[15]||(s[15]=[n("lujun9972",-1)])]),_:1}),s[20]||(s[20]=n(" 譯者：",-1)),l(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[16]||(s[16]=[n("geekpi",-1)])]),_:1}),s[21]||(s[21]=n(" 校對：",-1)),l(e,{href:"https://github.com/turbokernel"},{default:i(()=>[...s[17]||(s[17]=[n("turbokernel",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[22]||(s[22]=[n("LCTT",-1)])]),_:1}),s[25]||(s[25]=n(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:i(()=>[...s[23]||(s[23]=[n("Linux中國",-1)])]),_:1}),s[26]||(s[26]=n(" 榮譽推出",-1))])])}const y=p(m,[["render",u]]);export{M as __pageData,y as default};
